def comps(grid, col):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=col or (r,c) in seen: continue
       st=[(r,c)]; seen.add((r,c)); cells=[]
       while st:
        a,b=st.pop(); cells.append((a,b))
        for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
         if 0<=x<h and 0<=y<w and grid[x][y]==col and (x,y) not in seen: seen.add((x,y));st.append((x,y))
       rs=[x for x,y in cells];cs=[y for x,y in cells]
       out.append((len(cells),(min(rs),max(rs),min(cs),max(cs)),cells))
    return out
